# PowerShell Wizard Template for Windows & Cross-Platform PowerShell
# Generated by the wizard skill.
# Everything above the "STAGES" marker is the wizard library.

[CmdletBinding()]
param()

$ErrorActionPreference = "Stop"
$TOTAL_STAGES = 0
$_STAGE_INDEX = 0
$ENV_FILE = if ($env:ENV_FILE) { $env:ENV_FILE } else { ".env" }
$WRITTEN_ENV = [System.Collections.Generic.List[string]]::new()
$WRITTEN_SECRET = [System.Collections.Generic.List[string]]::new()
$SKIPPED = [System.Collections.Generic.List[string]]::new()

function Clear-ScreenSafe {
    try { [Console]::Clear() } catch { Write-Host "`n`n`n" }
}

function Show-Banner([string]$title) {
    Clear-ScreenSafe
    Write-Host "`n  $title" -ForegroundColor Cyan
    Write-Host "  $TOTAL_STAGES stages`n" -ForegroundColor DarkGray
    Write-Host "  You drive the browser; this wizard tells you exactly what to do." -ForegroundColor DarkGray
    Write-Host "  Stop any time with Ctrl+C.`n" -ForegroundColor DarkGray
    Pause-Step "Ready to start?"
}

function Show-Stage([string]$name) {
    Clear-ScreenSafe
    $script:_STAGE_INDEX++
    Write-Host "`n▸ Stage $script:_STAGE_INDEX/$TOTAL_STAGES · $name" -ForegroundColor Cyan
}

function Write-Say([string]$msg)  { Write-Host "  $msg" }
function Write-Step([string]$msg) { Write-Host "  • $msg" -ForegroundColor Cyan }
function Write-Note([string]$msg) { Write-Host "  $msg" -ForegroundColor DarkGray }
function Write-Warn([string]$msg) { Write-Host "  ⚠ $msg" -ForegroundColor Yellow }

function Open-UrlExternal([string]$url) {
    Write-Host "  ↗ opening $url" -ForegroundColor Green
    try {
        Start-Process $url
    } catch {
        Write-Warn "Could not open browser automatically, please open: $url"
    }
}

function Pause-Step([string]$msg = "Press Enter to continue") {
    Write-Host "  $msg " -ForegroundColor DarkGray -NoNewline
    [Console]::ReadLine() | Out-Null
}

function Confirm-Action([string]$question) {
    Write-Host "  ? $question [y/N] " -ForegroundColor Yellow -NoNewline
    $reply = [Console]::ReadLine()
    return ($reply -match "^[yY]")
}

function Get-ExistingEnv([string]$key) {
    if (-not (Test-Path $ENV_FILE)) { return $null }
    $lines = Get-Content $ENV_FILE -Encoding UTF8
    foreach ($line in $lines) {
        if ($line -match "^$([regex]::Escape($key))=(.*)$") {
            $val = $matches[1].Trim()
            if ($val.StartsWith("'") -and $val.EndsWith("'")) { $val = $val.Substring(1, $val.Length - 2) }
            elseif ($val.StartsWith('"') -and $val.EndsWith('"')) { $val = $val.Substring(1, $val.Length - 2) }
            return $val
        }
    }
    return $null
}

function Ask-Value([string]$key, [string]$prompt) {
    $existing = Get-ExistingEnv $key
    $promptText = "  $prompt "
    if ($existing) { $promptText += "[Enter keeps current] " }
    Write-Host $promptText -NoNewline
    $val = [Console]::ReadLine()
    if ([string]::IsNullOrWhiteSpace($val) -and $existing) { $val = $existing }
    return $val
}

function Ask-SecretValue([string]$key, [string]$prompt) {
    $existing = Get-ExistingEnv $key
    $promptText = "  $prompt "
    if ($existing) { $promptText += "[Enter keeps current] " }
    Write-Host $promptText -NoNewline
    $secure = Read-Host -AsSecureString
    $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
    $val = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
    if ([string]::IsNullOrWhiteSpace($val) -and $existing) { $val = $existing }
    return $val
}

function Write-EnvFile([string]$key, [string]$value) {
    $content = @()
    if (Test-Path $ENV_FILE) {
        $content = Get-Content $ENV_FILE -Encoding UTF8 | Where-Object { $_ -notmatch "^$([regex]::Escape($key))=" }
    }
    $content += "$key='$value'"
    [System.IO.File]::WriteAllLines((Resolve-Path -Path $ENV_FILE -ErrorAction SilentlyContinue ?? $ENV_FILE), $content, [System.Text.Encoding]::UTF8)
    $WRITTEN_ENV.Add($key)
    Write-Host "  ✓ wrote $key → $ENV_FILE" -ForegroundColor Green
}

function Set-GitHubSecret([string]$name, [string]$value) {
    $ghPath = Get-Command "gh" -ErrorAction SilentlyContinue
    if ($ghPath) {
        try {
            $process = Start-Process -FilePath "gh" -ArgumentList "secret", "set", $name -NoNewWindow -PassThru -RedirectStandardInput ([System.IO.Path]::GetTempFileName())
            # fallback pipe
            $value | gh secret set $name 2>$null
            $WRITTEN_SECRET.Add($name)
            Write-Host "  ✓ set GitHub secret $name" -ForegroundColor Green
            return
        } catch {}
    }
    $SKIPPED.Add("GitHub secret $name (run manually: gh secret set $name)")
    Write-Warn "Skipped GitHub secret $name: gh cli not available"
}

function Show-Finish {
    Clear-ScreenSafe
    Write-Host "`n  ✓ Setup complete" -ForegroundColor Green
    if ($WRITTEN_ENV.Count -gt 0) { Write-Note "Wrote $($WRITTEN_ENV.Count) values to $ENV_FILE" }
    if ($WRITTEN_SECRET.Count -gt 0) { Write-Note "Configured $($WRITTEN_SECRET.Count) GitHub secrets" }
    if ($SKIPPED.Count -gt 0) {
        Write-Host "`n  Manual steps remaining:" -ForegroundColor Yellow
        foreach ($s in $SKIPPED) { Write-Note "  - $s" }
    }
    Write-Host "`n"
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Define custom stages here
# ──────────────────────────────────────────────────────────────────────────

$TOTAL_STAGES = 1
Show-Banner "Setup Service"

Show-Stage "API Credentials"
Write-Say "Configuring third-party service credentials"
Open-UrlExternal "https://dashboard.example.com/apikeys"
Write-Step "Copy the API Key from the dashboard"
$keyVal = Ask-SecretValue "SERVICE_API_KEY" "Paste API Key:"
Write-EnvFile "SERVICE_API_KEY" $keyVal
Set-GitHubSecret "SERVICE_API_KEY" $keyVal

Show-Finish
